import{_ as i,a0 as n,w as p,s as d,I as s,x as t,a1 as o,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const H=JSON.parse('{"title":"怎样在 Linux 下用 SSH 搭建个人文件服务器 | LCTT x X-CMD","titleTemplate":false,"description":"怎样在 Linux 下用 SSH 搭建个人文件服务器 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在 Linux 下用 SSH 搭建个人文件服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在 Linux 下用 SSH 搭建个人文件服务器 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200323 How to create a personal file server with SSH on Linux","title":"怎样在 Linux 下用 SSH 搭建个人文件服务器","tag":"202005","desc":""},"relativePath":"202005/20200323 How to create a personal file server with SSH on Linux.md","filePath":"[post].md"}'),u={name:"202005/20200323 How to create a personal file server with SSH on Linux.md"};function f(m,e,S,g,h,x){const l=n("Link");return p(),d("div",null,[e[31]||(e[31]=s("h1",{id:"怎样在-linux-下用-ssh-搭建个人文件服务器",tabindex:"-1"},[t("怎样在 Linux 下用 SSH 搭建个人文件服务器 "),s("a",{class:"header-anchor",href:"#怎样在-linux-下用-ssh-搭建个人文件服务器","aria-label":"Permalink to “怎样在 Linux 下用 SSH 搭建个人文件服务器”"},"​")],-1)),e[32]||(e[32]=s("blockquote",null,[s("p",null,"通过 SSH 连接远程 Linux 系统很简单。下面是教程。")],-1)),e[33]||(e[33]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/27/120338v62cakrqnccpjckk.jpg",alt:""})],-1)),s("p",null,[e[1]||(e[1]=t("树莓派是一个有用且价格低廉的家庭服务器，可用于很多事情。我的树莓派最常用来做",-1)),o(l,{href:"https://opensource.com/article/18/3/print-server-raspberry-pi"},{default:r(()=>[...e[0]||(e[0]=[t("打印服务器",-1)])]),_:1}),e[2]||(e[2]=t("，可以在我的家庭网络中共享激光打印机，或作为个人文件服务器保存项目副本和其他数据。",-1))]),e[34]||(e[34]=a('<p>我的文件服务器有很多用途。假设说我现在有一个项目，比如一本新书，我想把我的工作和所有相关的文件都复制一份快照。这种场景下，我只需要把 <code>BookProject</code> 文件夹复制到文件服务器的 <code>BookBackup</code> 文件夹。</p><p>或者我现在正在清理我的本地文件时，发现一些我不需要的文件，但是我不确定是否要删除，我会把它们复制到文件服务器的 <code>KeepForLater</code> 文件夹。这是我日常 Linux 系统中清除杂乱的文件，并将不常用的文件卸载到个人文件服务器上的方便方法。</p><p>用树莓派或其他 Linux 系统搭建个人文件服务器不需要配置 NFS（<ruby>网络文件系统<rt>Network File System</rt></ruby>&gt;）或 CIFS（<ruby>通用互联网文件系统<rt>Common Internet File System</rt></ruby>）或改造其他的文件共享系统如 WebDAV。你可以很轻松的使用 SSH 来搭建远程文件服务器。下面是教程。</p><h3 id="在远程服务器上配置-sshd" tabindex="-1">在远程服务器上配置 SSHD <a class="header-anchor" href="#在远程服务器上配置-sshd" aria-label="Permalink to “在远程服务器上配置 SSHD”">​</a></h3>',4)),s("p",null,[e[4]||(e[4]=t("你的 Linux 系统可能已经安装了 SSH 守护进程（",-1)),e[5]||(e[5]=s("code",null,"sshd",-1)),e[6]||(e[6]=t("），甚至它已经默认运行了。如果没有，你可以使用你 Linux 发行版本上的任何控制面板来轻松配置 SSH。我在树莓派上运行了 ",-1)),o(l,{href:"https://arm.fedoraproject.org/"},{default:r(()=>[...e[3]||(e[3]=[t("Fedora ARM",-1)])]),_:1}),e[7]||(e[7]=t("，通过 Web 浏览器访问树莓派的 9090 端口，我可以远程访问控制面板。（在我的家庭网络中，树莓派的 IP 地址是 ",-1)),e[8]||(e[8]=s("code",null,"10.0.0.11",-1)),e[9]||(e[9]=t("，因此我连接的是 ",-1)),e[10]||(e[10]=s("code",null,"10.0.0.11:9090",-1)),e[11]||(e[11]=t("。）如果 SSH 守护进程没有默认运行，你可以在控制面板的“服务”里把它设置为开机启动。",-1))]),e[35]||(e[35]=a('<p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-sshd.png" alt="sshd in the list of system services" title="sshd in the list of system services"></p><p>你可以在系统服务列表里找到 <code>sshd</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-sshd-service.png" alt="slider to activate sshd" title="slider to activate sshd"></p><p>如果 <code>sshd</code> 没有开启，点击切换按钮打开它。</p><h3 id="你有账号吗" tabindex="-1">你有账号吗？ <a class="header-anchor" href="#你有账号吗" aria-label="Permalink to “你有账号吗？”">​</a></h3><p>你需要有个远程系统的账号。它可以与你本地系统的账号相同，也可以不同。</p><p>在流行的 Raspbian 发行版本上，默认的账号名是 <code>pi</code>。但是其他的 Linux 发行版本可能需要你在安装系统时就设置一个唯一的新用户。如果你不知道你的用户名，你可以用系统的控制面板创建一个。在我的树莓派上，我创建了一个 <code>jhall</code> 账号，与我日常用的 Linux 桌面机器的用户名相同。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-accounts_create-user.png" alt="Set up a new account on Fedora Server" title="Set up a new account on Fedora Server"></p><p>如果你用的是 Fedora 服务器，你可以点击“创建新账号”按钮。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora-server-control-panel-accounts.png" alt="Set password or SSH key" title="Set password or SSH key"></p><p>不要忘记设置密码或添加公钥。</p><h3 id="可选-添加公钥" tabindex="-1">可选：添加公钥 <a class="header-anchor" href="#可选-添加公钥" aria-label="Permalink to “可选：添加公钥”">​</a></h3><p>如果你把公钥添加到远程 Linux 系统上，你就可以不使用密码登录。这一步是可选的；如果你愿意，你仍可以用密码登录。</p><p>你可以在下面的文章中学到更多关于 SSH 密钥的信息：</p>',14)),s("ul",null,[s("li",null,[o(l,{href:"https://linux.cn/article-11947-1.html"},{default:r(()=>[...e[12]||(e[12]=[t("SSH 密钥管理工具",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://linux.cn/article-9451-1.html"},{default:r(()=>[...e[13]||(e[13]=[t("用 Seahorse 对 SSH 密钥进行图形化管理",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://opensource.com/article/19/4/gpg-subkeys-ssh-manage"},{default:r(()=>[...e[14]||(e[14]=[t("如何管理多个 SSH 密钥",-1)])]),_:1})]),s("li",null,[o(l,{href:"https://opensource.com/article/19/4/gpg-subkeys-ssh"},{default:r(()=>[...e[15]||(e[15]=[t("使用 GPG 密钥作为鉴权依据开启 SSH 访问",-1)])]),_:1})])]),e[36]||(e[36]=a('<h3 id="创建文件管理器的快捷方式" tabindex="-1">创建文件管理器的快捷方式 <a class="header-anchor" href="#创建文件管理器的快捷方式" aria-label="Permalink to “创建文件管理器的快捷方式”">​</a></h3><p>现在你已经在远程系统上启动 SSH 守护进程了，也设置了用户名和密码，最后一步就是在你本地的文件管理器中创建一个快捷方式，地址映射到远程 Linux 系统。我的桌面是 GNOME，但是在其他的 Linux 桌面上的基本操作步骤都是一样的。</p><h4 id="建立初始连接" tabindex="-1">建立初始连接 <a class="header-anchor" href="#建立初始连接" aria-label="Permalink to “建立初始连接”">​</a></h4><p>在 GNOME 的文件管理器中，在左边导航栏找到 “+其它位置” 按钮。点击它会出现一个 “连接到服务器” 提示框。在框中输入远程 Linux 服务器的地址，地址以 SSH 连接协议开头。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-locations.png" alt="Creating a shortcut in GNOME file manager" title="Creating a shortcut in GNOME file manager"></p><p>GNOME 文件管理器支持多种连接协议。要通过 SSH 进行连接，服务器地址请以 <code>sftp://</code> 或 <code>ssh://</code> 开头。</p><p>如果你远程 Linux 系统的用户名与本地的相同，那么你只需要输入服务器的地址和文件夹路径就可以了。比如要连接到我的树莓派的 <code>/home/jhall</code> 目录，我输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp://10.0.0.11/home/jhall</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-sftp.png" alt="GNOME file manager Connect to Server" title="GNOME file manager Connect to Server"></p><p>如果你远程 Linux 系统的用户名与本地的不同，你可以在远程系统地址前加 <code>@</code> 符号来指定远程系统的用户名。要连接到远程的 Raspbian 系统，你可能要输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp://pi@10.0.0.11/home/pi</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-other-sftp-username.png" alt="GNOME file manager Connect to Server" title="GNOME file manager Connect to Server"></p><p>如果你没有把公钥添加到远程服务器，那么你需要输入密码。如果你已经添加，GNOME 文件管理器应该会自动打开远程系统上的文件夹来让你跳转到不同的目录。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-remote-jhall.png" alt="GNOME file manager connection" title="GNOME file manager connection"></p><h4 id="创建一个快捷方式-之后就可以轻松连接服务器" tabindex="-1">创建一个快捷方式，之后就可以轻松连接服务器 <a class="header-anchor" href="#创建一个快捷方式-之后就可以轻松连接服务器" aria-label="Permalink to “创建一个快捷方式，之后就可以轻松连接服务器”">​</a></h4><p>在 GNOME 文件管理器中，这很简单。右击导航栏中远程系统的名字，选择“添加书签”。这一步操作就创建了连接到远程路径的快捷方式。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager-remote-jhall-add-bookmark.png" alt="GNOME file manager - adding bookmark" title="GNOME file manager - adding bookmark"></p><p>如果你想把标签中的快捷方式改成一个更容易记的名字，你可以右击快捷方式选择“重命名”。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>通过 SSH 连接到远程 Linux 系统是很简单的事。你可以用相同的方式连接到家庭文件服务器以外的其他系统。我还创建了一个能让我立即访问我的提供商 Web 服务器上的文件的快捷方式，和另一个能迅速打开我的项目服务器的文件夹的快捷方式。SSH 使它成为一个安全的连接；所有的传输都是加密的。当我通过 SSH 打开远程的文件时，我可以像在本地操作一样使用 GNOME 文件管理器轻松打开远程文件。</p><hr>',21)),s("p",null,[e[17]||(e[17]=t("via: ",-1)),o(l,{href:"https://opensource.com/article/20/3/personal-file-server-ssh"},{default:r(()=>[...e[16]||(e[16]=[t("https://opensource.com/article/20/3/personal-file-server-ssh",-1)])]),_:1})]),s("p",null,[e[22]||(e[22]=t("作者：",-1)),o(l,{href:"https://opensource.com/users/jim-hall"},{default:r(()=>[...e[18]||(e[18]=[t("Jim Hall",-1)])]),_:1}),e[23]||(e[23]=t(" 选题：",-1)),o(l,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[19]||(e[19]=[t("lujun9972",-1)])]),_:1}),e[24]||(e[24]=t(" 译者：",-1)),o(l,{href:"https://github.com/lxbwolf"},{default:r(()=>[...e[20]||(e[20]=[t("lxbwolf",-1)])]),_:1}),e[25]||(e[25]=t(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:r(()=>[...e[21]||(e[21]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[28]||(e[28]=t("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[26]||(e[26]=[t("LCTT",-1)])]),_:1}),e[29]||(e[29]=t(" 原创编译，",-1)),o(l,{href:"https://linux.cn/"},{default:r(()=>[...e[27]||(e[27]=[t("Linux中国",-1)])]),_:1}),e[30]||(e[30]=t(" 荣誉推出",-1))])])}const L=i(u,[["render",f]]);export{H as __pageData,L as default};
